const items = $input.all();
const out = [];
const seen = new Set();
for (const item of items) {
  const j = item.json;
  const text = (j.postSnippet || j.text || '').toString();
  const url = (j.postUrl || j.url || '').toString();
  const id = url.includes('activity-') ? url.split('activity-')[1].split('?')[0] : url || text.slice(0,80);
  if (!id || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: { ...j, post_id: id, post_content: text, post_url: url } });
}
return out;
